"""Assemble the human report exclusively from measured local artifacts."""
import json
from pathlib import Path
from datetime import datetime

ROOT = Path(__file__).resolve().parent
read = lambda p: json.loads((ROOT / p).read_text(encoding='utf-8-sig'))
def table(headers, rows):
    return '| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+'\n'.join('| '+' | '.join(str(v) for v in row)+' |' for row in rows)+'\n'
scores = read('out/scores.json')
variants = list(dict.fromkeys(row['variant'] for row in scores))
environment = read('out/environment.json')
provenance = read('provenance.json')
runtime = read('runtime-provenance-official.json')
verdicts=[]
for variant in variants:
    subset=[r for r in scores if r['variant']==variant and r['level']=='char']
    recalls=all(sum(p['found'] for r in subset if r['scale']==s for p in r['plants'] if p['category']==c)/sum(1 for r in subset if r['scale']==s for p in r['plants'] if p['category']==c)>=threshold for s,threshold in [(1,.85),(2,.95)] for c in ['email','phone','card'])
    found=[p for r in subset for p in r['plants'] if p['found']]
    loc=bool(found) and all(p['coverage'][2]>=.98 for p in found)
    fast=all(r['warm']<=1.5 for r in subset if r['scale']==1)
    verdicts.append(f"**{variant}: {'PASS on measured desktop gates' if recalls and loc and fast else 'FAIL'}** (recall {'PASS' if recalls else 'FAIL'}, derived-character localization {'PASS' if loc else 'FAIL'}, desktop speed {'PASS' if fast else 'FAIL'}).")
parts=['# S1b: PP-OCRv5 via Rust ort\n',f"Measured {datetime.now().date()}. Bounded synthetic-corpus evidence only. No real personal files were scanned.\n",'\n'.join(verdicts)+'\n\nThe four-core laptop gate and network-isolated execution remain unverified. This spike does not by itself clear release or redistribution review.\n', '## Method\n\nThe unchanged S1 corpus and its original labels are scored with the same category regex/Luhn detection, canonical matching and one-to-one occurrence assignment. PNG and truth hashes are verified before each run. No fixture regeneration, spelling repair or ground-truth-assisted OCR occurs. Recall counts exact normalized planted values; unmatched findings and those overlapping benign look-alikes are counted separately. Glyph coverage means union of browser character rectangles, not an ink mask; misses contribute zero to end-to-end coverage. Padding is in original device pixels.\n\nThe JSON retains line text, quadrilaterals and a whole-line `words` entry for S1 shape compatibility. `chars` contains decoded CTC tokens and timestep indices; the inverse crop projection maps their horizontal ranges into original raster coordinates. This is approximate sub-line geometry. Both coverage modes use identical text, so localization cannot alter recall. S1b scoring lives entirely here and imports S1 primitives read-only; no S1 file was changed.\n', (ROOT/'out/metrics-report.md').read_text(encoding='utf-8'), '## Pipeline and reference comparison\n\nDetection uses BGR input, maximum side 960, nearest multiple of 32, ImageNet mean/std, DB probability threshold 0.3, mean box score threshold 0.6 and unclip ratio 1.5. Outer contours produce minimum-area rectangles; unclip expands the rectangle by area/perimeter distance. Crop rectification uses a perspective transform, then height-48 recognition with aspect preservation, minimum width 320, zero normalized padding, BGR mean/std 0.5 and greedy CTC collapse. Blank is dictionary index zero; space follows the supplied dictionary. No angle classifier is used. Rectangular unclip, crop interpolation and contour rounding are implementation differences from RapidOCR; the oracle comparison is not a claim of bit-equivalent preprocessing.\n']
comparisons=[]
for variant in variants:
    p=ROOT/'out/oracle'/variant/'comparison.json'
    if not p.exists():
        comparisons.append([variant,'NOT RUN','','','','','',''])
        continue
    oracle=json.loads(p.read_text(encoding='utf-8'))
    for x in oracle['comparison']:
        comparisons.append([variant,x['id'],x['oracle_lines'],x['rust_lines'],x['matched_lines'],x['exact_lines'],x['total_edit_distance'],f"{x['unmatched_oracle_lines']}/{x['unmatched_rust_lines']}"])
parts += [table(['Variant','Image ID','Reference lines','Rust lines','IoU-matched','Exact text matches','Character edits','Unmatched ref/Rust'],comparisons),'RapidOCR '+read('out/oracle/'+variants[0]+'/comparison.json')['rapidocr_version']+' / Python ONNX Runtime '+read('out/oracle/'+variants[0]+'/comparison.json')['onnxruntime_version']+' is a correctness oracle only. CPU, classifier disabled, same official model files/dictionaries and matching thresholds. Greedy geometric line pairing uses IoU >=0.2; edit counts include substitutions, insertions and deletions on matched lines. Unmatched lines are reported separately. Full masked pair data/configuration: `out/oracle/<variant>/comparison.json`. Python results are never substituted for Rust scores or timings.\n','## Hardware and timing interpretation\n\n'+f"CPU: {environment['cpu']}; {environment['physicalCores']} physical cores / {environment['logicalCores']} logical processors, Windows {environment['architecture']}. Rust uses four intra-op threads, one inter-op thread and sequential CPU execution. Sessions load once; first image warmup excluded. Decode and final JSON serialization are outside timing; all det/rec preprocessing, inference, DB geometry and CTC output construction are inside. One sample per image; maximum observed 1x sample decides the speed gate. No CPU affinity restriction, laptop simulation or statistical confidence claim. S1's default runtime threads differ, so speed comparison is descriptive. Final timing run must be performed without concurrent spike builds/oracle inference.\n",'## Model provenance and licensing\n\nAll exports are published by the official PaddlePaddle account, pinned to immutable Hugging Face revisions. Each official model card explicitly declares `license: apache-2.0`; this is a weight-specific statement, rather than inference from a code repository license. The matching dictionary is extracted from each recognizer configuration, not borrowed from another recognizer. Full model cards/configurations remain in ignored `models/`.\n',table(['File','Measured bytes','SHA-256','Source','License statement'],[[r['file'].replace('\\','/'),r['bytes'],r['sha256'],f"[download]({r['url']})",f"[Apache-2.0 model card]({r['license_url']})"] for r in provenance]),'## Runtime and packaging\n\n`ort =2.0.0-rc.10`, independent edition-2024 Cargo workspace. The initial `download-binaries` attempt selected a static pyke ORT distribution that could not link against this host MSVC runtime; it is not the measured runtime. The final runner uses `std` + `load-dynamic`, no automatic binary download, and the official Microsoft CPU runtime selected through `ORT_DYLIB_PATH`. No CUDA/DirectML provider is registered. The unused downloaded pyke archive is recorded separately in `runtime-provenance.json`; it is not a proposed redistributable dependency.\n',table(['Runtime artifact','Bytes','SHA-256'],[[runtime['url'],runtime['bytes'],runtime['sha256']]]+[[r['file'].replace('\\','/'),r['bytes'],r['sha256']] for r in runtime['artifacts']]),f"\n[Microsoft ONNX Runtime 1.22.0 license]({runtime['license_url']}): MIT. The extracted `ThirdPartyNotices.txt` accompanies the runtime and must remain part of packaging review. ZIP size includes build/debugging artifacts, not only inference DLLs.\n"]
models=[r for r in provenance if r['file'].endswith('.onnx')]
parts.append(table(['Variant','Det+rec bytes','Dictionary bytes'],[[v,sum(r['bytes'] for r in models if v+'_' in r['file']),next(r['bytes'] for r in provenance if r['file'].endswith(v+'_dict.txt'))] for v in variants]))
parts += ['Models and the runtime are read exclusively from local paths after explicit acquisition; Rust has no fetch feature. **Network-disabled execution: NOT TESTED.** A Windows token membership check returned Administrator=false; the running Windows Firewall service requires elevation to install blocking rules. Adapter/firewall settings were not changed. Structural absence of downloads is not a substitute for network isolation evidence.\n','## Reproduction and validation\n\nSee [README.md](README.md). `provenance.json` and `runtime-provenance-official.json` carry exact URLs/hashes; ignored `out/` holds configuration, timings, raw synthetic OCR, masked scores and oracle comparison. No changes were made to `crates/`, root Cargo files or `.github/`; no commit/push/publication was performed.\n']
p=ROOT/'out/validation.json'
if p.exists():
    validation=json.loads(p.read_text())
    parts.append(table(['Command','Result'],[[x['command'],x['result']] for x in validation]))
parts.append('Full dependency advisory audit fails: `anyhow 1.0.100` (RUSTSEC-2026-0190), `imageproc 0.25.0` (RUSTSEC-2026-0115, RUSTSEC-2026-0116, RUSTSEC-2026-0117), and unmaintained transitive `paste` (RUSTSEC-2024-0436) / `ttf-parser` (RUSTSEC-2026-0192). License, source and bans checks pass; no advisory suppressions were added. Dependency updates were not performed under the supplied no-update boundary. Exact audit evidence is in `out/validation-5.log`. This is a synthetic-only spike, not a shipping dependency approval.\n\nReference line text and detection counts still differ from Rust, especially with server detection; the comparison tables expose that remaining uncertainty. These results characterize this Rust pipeline and configuration, rather than establishing the maximum accuracy of every PP-OCR deployment. Compressed release bundle size was not measured. Model-card Apache-2.0 declarations are recorded; no standalone dictionary license or training-data license review was established in this spike.\n')
(ROOT/'RESULTS.md').write_text('\n'.join(parts),encoding='utf-8')
print('Wrote RESULTS.md from measured local artifacts')
